 import { execSync } from "child_process";
 import fs from "fs";
 import path from "path";
 import os from "os";
 import jsyaml from "js-yaml";

 const WEBSITE_REPO = "https://github.com/processing/p5.js-website.git";
 const REF_DIR = "src/content/reference/en";
+const ASSETS_DIR = "public/assets";
 const OUT_FILE = path.resolve("src/data/reference.generated.json");
+const ASSETS_OUT_FILE = path.resolve("src/data/p5Assets.generated.json");

+// Match p5.js load* calls that reference /assets/<name> or "./<name>" files.
+// Captures the quote char and the path so we can rewrite to a placeholder
+// token that getExampleHtml substitutes with the real data: URI at render
+// time. Using placeholders (instead of inlining the base64 blob) keeps the
+// reference JSON small — the same asset (e.g. teapot.obj) is referenced by
+// dozens of examples and would otherwise be duplicated hundreds of times.
+const ASSET_PATH_RE = /(['"])\/assets\/([^'"\\\s)]+)\1/g;
+const RELATIVE_ASSET_RE = /(['"])\.\/([^'"\\\s)]+)\1/g;
+const ASSET_PLACEHOLDER_PREFIX = "__P5_ASSET__";
+
+// Extensions safe to bundle as base64 data: URIs. Large media (audio/video)
+// is skipped to avoid bloating the asset map — those example paths are left
+// untouched (the example will simply fail to load that asset in-preview,
+// which is preferable to a multi-MB JSON blob).
+const SKIP_EXTS = new Set([".mp3", ".ogg", ".wav", ".mp4", ".mov", ".webm", ".ogv"]);
+const MAX_ASSET_BYTES = 1_500_000; // 1.5 MB per file — skip larger assets
+
+const MIME_BY_EXT = {
+  ".obj": "text/plain",
+  ".mtl": "text/plain",
+  ".glsl": "text/plain",
+  ".frag": "text/plain",
+  ".vert": "text/plain",
+  ".txt": "text/plain",
+  ".csv": "text/csv",
+  ".json": "application/json",
+  ".xml": "application/xml",
+  ".jpg": "image/jpeg",
+  ".jpeg": "image/jpeg",
+  ".png": "image/png",
+  ".gif": "image/gif",
+  ".otf": "font/otf",
+  ".ttf": "font/ttf",
+};
+
+function mimeForExt(ext) {
+  return MIME_BY_EXT[ext.toLowerCase()] || "application/octet-stream";
+}
+
+function buildDataUri(filePath) {
+  const ext = path.extname(filePath).toLowerCase();
+  if (SKIP_EXTS.has(ext)) return null;
+  try {
+    const stat = fs.statSync(filePath);
+    if (stat.size > MAX_ASSET_BYTES) {
+      console.log(`  Skipping large asset (${stat.size} bytes): ${path.basename(filePath)}`);
+      return null;
+    }
+    const buf = fs.readFileSync(filePath);
+    return `data:${mimeForExt(ext)};base64,${buf.toString("base64")}`;
+  } catch {
+    return null;
+  }
+}
+
+function writeAssetMap(assetMap) {
+  fs.writeFileSync(ASSETS_OUT_FILE, JSON.stringify(assetMap, null, 2), "utf-8");
+  console.log(`Generated ${ASSETS_OUT_FILE}`);
+  console.log(`  ${Object.keys(assetMap).length} bundled assets`);
+}
+
 // p5 version stamp: read from the bundle-p5 generated artefact so the
 // reference metadata always matches the p5 version actually bundled.
 function readP5Version() {
   const versionFile = path.resolve("src/utils/p5Version.ts");
   try {
     const content = fs.readFileSync(versionFile, "utf-8");
     const m = content.match(/p5Version\s*=\s*"([^"]+)"/);
     if (m) return m[1];
   } catch {}
   return "2.3.0";
 }

 const MDX_FRONTMATTER_RE = /^---\n([\s\S]*?)\n---/;

 function parseMdxFrontmatter(content) {
   const match = content.match(MDX_FRONTMATTER_RE);
   if (!match) return null;
   return jsyaml.load(match[1]);
 }

 function stripHtml(html) {
   if (!html) return "";
   return html
     .replace(/<p>/gi, "")
     .replace(/<\/p>/gi, "")
     .replace(/<br\s*\/?>/gi, " ")
     .replace(/<code>/gi, "")
     .replace(/<\/code>/gi, "")
     .replace(/<a[^>]*>/gi, "")
     .replace(/<\/a>/gi, "")
     .replace(/<[^>]+>/g, "")
     .replace(/&lt;/g, "<")
     .replace(/&gt;/g, ">")
     .replace(/&amp;/g, "&")
     .replace(/&quot;/g, '"')
     .replace(/\n{2,}/g, "\n")
     .trim();
 }

 function flattenParams(params) {
   if (!Array.isArray(params)) return [];
   return params.map((p) => ({
     name: p.name,
     type: p.type || "Any",
     optional: p.optional === 1 || p.optional === true,
     description: stripHtml(p.description || ""),
   }));
 }

 function buildSyntax(name, params) {
   if (!params || params.length === 0) return `${name}()`;
   const parts = params.map((p) => (p.optional ? `[${p.name}]` : p.name));
   return `${name}(${parts.join(", ")})`;
 }

 function mapP5TypeToKeyboardType(typeStr) {
   const t = (typeStr || "").toLowerCase();
   if (t.includes("color")) return "color";
   if (t.includes("string")) return "string";
   if (t.includes("number") || t.includes("int") || t.includes("float")) return "number";
   if (t.includes("array") || t.includes("[]")) return "array";
   if (t.includes("boolean") || t.includes("bool")) return "boolean";
   return "number";
 }

 function getKeyboardParamTypes(params) {
   if (!params || params.length === 0) return [];
   return params.map((p) => mapP5TypeToKeyboardType(p.type));
 }

 function buildOutput(byName, byModule, byClass) {
   const classes = Object.keys(byClass).sort();
   const functionNames = Object.keys(byName).filter(
     (k) => byName[k].itemtype === "method"
   ).sort();
   const keyboardFunctions = functionNames.slice(0, 100).map((name) => {
     const s = byName[name];
     return {
       label: s.name,
       insert: s.name + "()",
       paramTypes: getKeyboardParamTypes(s.params),
     };
   });

   return {
     byName,
     byModule,
     byClass,
     classes,
     keyboardFunctions,
     functionNames,
     metadata: {
       generatedAt: new Date().toISOString(),
       p5Version: readP5Version(),
       symbolCount: Object.keys(byName).length,
     },
   };
 }

 function writeOutput(output) {
   fs.writeFileSync(OUT_FILE, JSON.stringify(output, null, 2), "utf-8");
   console.log(`Generated ${OUT_FILE}`);
   console.log(`  ${output.metadata.symbolCount} symbols`);
   console.log(`  ${Object.keys(output.byModule).length} modules`);
   console.log(`  ${output.classes.length} classes`);
 }

 function generateFromRepo() {
   const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "p5-ref-"));
   console.log(`Cloning ${WEBSITE_REPO} ...`);

   try {
     execSync(
       `git clone --depth 1 --single-branch "${WEBSITE_REPO}" "${tmpDir}"`,
       { stdio: "pipe", timeout: 120_000 }
     );
   } catch (e) {
     console.error("Failed to clone p5.js-website repo:", e.message);
     console.log("Falling back to stub data...");
     generateStub();
     return;
   }

   const refRoot = path.join(tmpDir, REF_DIR);
