+    const filePath = assetByBasename.get(basename);
+    if (!filePath) return null;
+    const uri = buildDataUri(filePath);
+    if (!uri) return null;
+    const token = `${ASSET_PLACEHOLDER_PREFIX}${basename}${ASSET_PLACEHOLDER_PREFIX}`;
